import{_ as l,C as i,o as c,c as h,j as t,a as r,E as o,ak as d}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"布局","description":"","frontmatter":{},"headers":[],"relativePath":"design/layout.md","filePath":"design/layout.md","lastUpdated":1790377131000}'),s={name:"design/layout.md"};function n(p,e,x,m,g,u){const a=i("XhTokenTable");return c(),h("div",null,[e[0]||(e[0]=t("h1",{id:"布局",tabindex:"-1"},[r("布局 "),t("a",{class:"header-anchor",href:"#布局","aria-label":'Permalink to "布局"'},"​")],-1)),e[1]||(e[1]=t("p",null,"布局的尺度只有一把尺：4px 网格。间距、控件高度、字段宽度、面的内衬、断点全部锚在它上面，组件里没有第二套数。",-1)),e[2]||(e[2]=t("h2",{id:"间距阶梯",tabindex:"-1"},[r("间距阶梯 "),t("a",{class:"header-anchor",href:"#间距阶梯","aria-label":'Permalink to "间距阶梯"'},"​")],-1)),o(a,{kind:"space",names:["--xh-space-0_5","--xh-space-1","--xh-space-1_5","--xh-space-2","--xh-space-2_5","--xh-space-3","--xh-space-4","--xh-space-5","--xh-space-6","--xh-space-7","--xh-space-8"],notes:{"--xh-space-0_5":"半阶补偿：图标基线、几何对齐","--xh-space-1":"贴在一起的：标签贴控件、说明贴控件、图标贴文字","--xh-space-1_5":"半阶补偿：紧凑控件","--xh-space-2":"同一组里的相邻项：控件内图标与文字、集合标题与集合","--xh-space-2_5":"半阶补偿","--xh-space-3":"控件的行内内衬（md）","--xh-space-4":"不同信息组之间","--xh-space-6":"区块之间","--xh-space-8":"页面级分段"}}),e[3]||(e[3]=d('<p>规则：所有 padding、gap 与布局间距走令牌；2 / 6 / 10 只用于图标基线、紧凑控件与几何补偿，不出现 5 / 7 / 9 / 13 / 15 这类散值；信息关系越紧密间距越小，不同信息组至少提升一个档位。</p><p>面的内衬只走 <code>--xh-surface-*</code>（<code>px-sm / md</code>、<code>py-sm / md</code>、<code>pad-xs … lg</code>），页面分段走 <code>--xh-section-py-*</code>，布局组件的列隙走 <code>--xh-layout-gap-xs … xl</code>、列的最小宽走 <code>--xh-layout-col-min-xs … lg</code>。</p><h2 id="控件高度与密度" tabindex="-1">控件高度与密度 <a class="header-anchor" href="#控件高度与密度" aria-label="Permalink to &quot;控件高度与密度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>密度</th><th style="text-align:right;">sm</th><th style="text-align:right;">md</th><th style="text-align:right;">lg</th></tr></thead><tbody><tr><td>comfortable（缺省）</td><td style="text-align:right;">32px</td><td style="text-align:right;">36px</td><td style="text-align:right;">40px</td></tr><tr><td>compact</td><td style="text-align:right;">28px</td><td style="text-align:right;">32px</td><td style="text-align:right;">36px</td></tr></tbody></table><ul><li>md 是缺省尺寸；同一 <code>size</code> 不随断点自动改变高度。</li><li>图标按钮的视觉盒遵循同一高度；粗指针命中区至少 44×44px，用伪元素扩展，不改布局盒。</li><li>尺寸档同时换行内内衬（<code>--xh-control-px-sm / md / lg</code> = 8 / 12 / 16px）、内部间隙（<code>--xh-control-gap-*</code> = 4 / 8 / 12px）、字号（<code>--xh-control-font-*</code>）与图标（16 / 20 / 24px）。</li><li>密度（<code>data-density=&quot;compact&quot;</code>）只收紧高度、内距与间隙，不缩字号和字形。</li><li>正方盒（Avatar、色块、图标包装）走 <code>--xh-control-box-sm / md / lg</code> = 32 / 40 / 48px。</li></ul><h2 id="字段的宽度" tabindex="-1">字段的宽度 <a class="header-anchor" href="#字段的宽度" aria-label="Permalink to &quot;字段的宽度&quot;">​</a></h2><p>单行字段不传尺寸时一族同宽：根缺省 <code>inline-size: var(--xh-control-w)</code>（16rem），宽度不随内容走——选中一条很长的选项触发器也不变宽。另有一条底线 <code>--xh-control-min-w</code>（12rem）：字段被 flex / grid 容器压缩时收到这里为止，容器比底线还窄时收成容器宽，不越出去。要撑满表单列在根上写 <code>inline-size: 100%</code>。</p><p>例外只有登记过的几件：日期范围选择器起止两组按日的段位放不进 16rem，缺省按内容撑开；分格输入由格数与格宽定宽；对话输入条铺满宿主；表单字段（Field）的控件铺满表单列。槽名与放开方式见 <a href="/guide/styling#输入类控件的缺省宽度与最小宽度">皮肤与样式分层 · 输入类控件的缺省宽度与最小宽度</a>。</p><h2 id="侧栏的宽度" tabindex="-1">侧栏的宽度 <a class="header-anchor" href="#侧栏的宽度" aria-label="Permalink to &quot;侧栏的宽度&quot;">​</a></h2>',9)),o(a,{names:["--xh-sider-w","--xh-sider-collapsed-w"],notes:{"--xh-sider-w":"展开","--xh-sider-collapsed-w":"折叠成图标栏"}}),e[4]||(e[4]=d('<p>页面侧栏的两档宽度只有这一处真源：<a href="/components/layout">Layout</a> 的侧栏与 <a href="/components/side-nav">SideNav</a> 缺省都读这两支令牌。改令牌，两件一起换宽；只改一处时写该组件的覆盖槽（<code>--xh-layout-sider-w</code> / <code>--xh-layout-sider-collapsed-w</code>、<code>--xh-side-nav-w</code> / <code>--xh-side-nav-collapsed-w</code>），槽压过令牌。SideNav 放进 Layout 的侧栏时，侧栏内衬缺省归零，导航正好铺满侧栏。</p><h2 id="断点" tabindex="-1">断点 <a class="header-anchor" href="#断点" aria-label="Permalink to &quot;断点&quot;">​</a></h2>',2)),o(a,{names:["--xh-breakpoint-sm","--xh-breakpoint-md","--xh-breakpoint-lg","--xh-breakpoint-xl"],notes:{"--xh-breakpoint-sm":"手机横屏起","--xh-breakpoint-md":"平板；浮层里的多列面板在此以下改单列","--xh-breakpoint-lg":"桌面；Layout 的 siderBreakpoint 常取这一档，以下折叠侧栏","--xh-breakpoint-xl":"宽桌面"}}),e[5]||(e[5]=d('<p>断点只用 <code>min-width</code> 自窄到宽依次接管，写了哪档就在哪档切换；只在窄档生效的规则写它的补集 <code>not all and (min-width: …)</code>，不写 <code>max-width</code>（它在断点值上与 <code>min-width</code> 同时成立），也不写区间写法 <code>(width &lt; …)</code>（Safari 16.4 起才认）。媒体查询不改选择器权重。多数&quot;窄处坏掉&quot;的问题不靠断点解决：flex-wrap、<code>min-inline-size: 0</code>、<code>overflow-wrap</code>、把死地板改成能让步的 <code>min(…, 100%)</code>，这些规则在窄视口与窄容器（1280 宽屏里的 260px 侧栏）两种情形下同时成立。</p><h2 id="布局组件" tabindex="-1">布局组件 <a class="header-anchor" href="#布局组件" aria-label="Permalink to &quot;布局组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>管什么</th></tr></thead><tbody><tr><td><a href="/components/layout">Layout</a></td><td>页面骨架：页头、侧栏、内容、页脚；侧栏可折叠、可在断点以下改成覆盖层</td></tr><tr><td><a href="/components/flex">Flex</a></td><td>一维排列，间隙走 <code>--xh-layout-gap-*</code></td></tr><tr><td><a href="/components/grid">Grid</a></td><td>二维栅格，列的最小宽走 <code>--xh-layout-col-min-*</code></td></tr><tr><td><a href="/components/masonry">Masonry</a></td><td>瀑布流</td></tr><tr><td><a href="/components/splitter">Splitter</a> / <a href="/components/resizable">Resizable</a></td><td>可拖动分栏与可拖动尺寸</td></tr><tr><td><a href="/components/separator">Separator</a></td><td>分隔线，取 <code>--xh-border-subtle</code></td></tr><tr><td><a href="/components/scroll-area">ScrollArea</a></td><td>组件内滚动面，自绘条或原生细条按 <a href="/guide/theme#组件内滚动">组件内滚动</a> 归档</td></tr></tbody></table><h2 id="表单排布" tabindex="-1">表单排布 <a class="header-anchor" href="#表单排布" aria-label="Permalink to &quot;表单排布&quot;">​</a></h2><p><a href="/components/form">Form</a> 四种排布：<code>vertical</code>（缺省，纵向一列）、<code>horizontal</code>（标签左置两列，整表标签列宽由 <code>--xh-form-label-w</code> 统一对齐）、<code>inline</code>（横向一行流，放不下自动换行）、<code>grid</code>（等宽列网格，列数 1 – 4 逐断点声明，单个字段可跨列或占满整行）。字段标签贴控件 <code>--xh-space-1</code>，说明与错误文案同样 <code>--xh-space-1</code>，字段与字段之间走 <code>--xh-form-gap</code>（缺省 <code>--xh-stack-gap-md</code>）。</p><h2 id="浮层尺寸" tabindex="-1">浮层尺寸 <a class="header-anchor" href="#浮层尺寸" aria-label="Permalink to &quot;浮层尺寸&quot;">​</a></h2><p>锚定浮层的宽高走 <code>--xh-overlay-*</code>：面板最小宽 12rem、菜单最小宽 10rem、最大宽 sm / md / lg / xl = 16 / 20 / 24 / 48rem、菜单最大高 20rem；Dialog 的 sheet 宽 sm / md / lg = 24 / 32 / 48rem，Drawer 宽 sm / md / lg = 16 / 20 / 28rem。锚定浮层同时接可用高度与可用宽度：视口放不下时先收自己，再翻面。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/shape">形状与边界</a> · <a href="/design/typography">字体</a></li><li>指南：<a href="/guide/styling">皮肤与样式分层</a> · <a href="/guide/position">浮层定位</a></li></ul>',9))])}const _=l(s,[["render",n]]);export{f as __pageData,_ as default};
